W = H = 1024
HERE = os.path.dirname(os.path.abspath(__file__))
OUT_DIR = os.path.join(HERE, "out")

# ============================ palette ============================
INK     = (18, 20, 24)
PAPER   = (247, 245, 240)
RULE    = (60, 62, 66)
MID     = (120, 122, 126)
WHITE   = (255, 255, 255)
ME   = (168, 32, 26)    # middle east red
CN   = (170, 68, 12)    # china orange
US   = (22, 78, 140)    # usa blue
MK   = (16, 110, 62)    # markets green
UK   = (94, 44, 130)    # ukraine purple
RU   = (110, 30, 30)    # russia maroon
AF   = (150, 100, 10)   # africa ochre
SP   = (10, 90, 100)    # sport teal
HL   = (26, 28, 32)     # health slate
TC   = (40, 90, 120)    # tech
SC   = (90, 80, 20)     # space
UC   = (120, 50, 110)   # us-china
BAND = (236, 232, 224)
SEA  = (214, 222, 228)
LANDC= (198, 202, 200)
EDGE = (150, 156, 156)

REGION_COLOR = {
    "MIDDLE EAST": ME, "CHINA": CN, "UNITED STATES": US, "MARKETS": MK,
    "US-CHINA": UC, "UKRAINE": UK, "AFRICA": AF, "RUSSIA": RU,
    "SPORT": SP, "HEALTH": HL, "TECH": TC, "SPACE": SC,
}

# ============================ canvas ============================
_buf = bytearray()
for _i in range(W * H):
    _buf += bytes(PAPER)

def px(x, y, c):
    if 0 <= x < W and 0 <= y < H:
        i = (y * W + x) * 3
        _buf[i:i + 3] = bytes(c)

def rect(x0, y0, x1, y1, c):
    x0 = max(0, int(x0)); y0 = max(0, int(y0))
    x1 = min(W, int(x1)); y1 = min(H, int(y1))
    if x1 <= x0 or y1 <= y0:
        return
    row = bytes(c) * (x1 - x0)
    for y in range(y0, y1):
        i = (y * W + x0) * 3
        _buf[i:i + len(row)] = row

def hline(x0, x1, y, c, t=1):
    rect(x0, y, x1, y + t, c)

def vline(x, y0, y1, c, t=1):
    rect(x, y0, x + t, y1, c)

def frame(x0, y0, x1, y1, c, t=1):
    hline(x0, x1, y0, c, t); hline(x0, x1, y1 - t, c, t)
    vline(x0, y0, y1, c, t); vline(x1 - t, y0, y1, c, t)

# ============================ polygon fill ============================
def fill_polygon(pts, c):
    n = len(pts)
    if n < 3:
        return
    ys = [p[1] for p in pts]
    y0 = max(0, int(math.floor(min(ys)))); y1 = min(H - 1, int(math.ceil(max(ys))))
    for y in range(y0, y1 + 1):
        yc = y + 0.5
        xs = []
        j = n - 1
        for i in range(n):
            yi = pts[i][1]; xi = pts[i][0]
            yj = pts[j][1]; xj = pts[j][0]
            if (yi <= yc < yj) or (yj <= yc < yi):
                xs.append(xi + (yc - yi) * (xj - xi) / (yj - yi))
            j = i
        if not xs:
            continue
        xs.sort()
        for k in range(0, len(xs) - 1, 2):
            a = int(math.ceil(xs[k] - 0.5))
            b = int(math.floor(xs[k + 1] - 0.5))
            if b < a:
                continue
            if a < 0: a = 0
            if b > W - 1: b = W - 1
            base = (y * W) * 3
            cb = bytes(c)
            for x in range(a, b + 1):
                _buf[base + x * 3: base + x * 3 + 3] = cb

# ============================ font ============================
_doc = json.loads(gzip.decompress(base64.b64decode(FONT_B64)))
F_REG = _doc[1]   # text font: caps, lower, digits, punctuation
F_DSP = _doc[2]   # display font: wide caps for masthead and headers
SCALE = 1.0 / 256.0   # em = 256 design units (cap height 187, descender -53)

_cache = {}

def glyph(ch, display):
    key = (ch, display)
    if key in _cache:
        return _cache[key]
    if display and ch in F_DSP:
        g = F_DSP[ch]
    elif ch in F_REG:
        g = F_REG[ch]
    else:
        g = None
    _cache[key] = g
    return g

def draw_text(x, y, s, size, color=INK, display=False, tracking=0):
    sc = size * SCALE
    cx = float(x)
    for ch in s:
        g = glyph(ch, display)
        if g is None:
            cx += 0.55 * size
            continue
        adv, rings = g
        if ch != ' ':
            for ring in rings:
                pts = [(cx + p[0] * sc, y - p[1] * sc) for p in ring]
                fill_polygon(pts, color)
        cx += adv * sc + tracking
    return cx - x

def text_w(s, size, display=False, tracking=0):
    sc = size * SCALE
    w = 0.0
    for ch in s:
        g = glyph(ch, display)
        if g is None:
            w += 0.55 * size
        else:
            w += g[0] * sc
        w += tracking
    return max(0.0, w - tracking) if s else 0.0

def wrap(s, size, maxw, display=False):
    words = s.split()
    lines = []
    cur = ""
    for w0 in words:
        t = (cur + " " + w0).strip()
        if text_w(t, size, display) <= maxw or not cur:
            cur = t
        else:
            lines.append(cur)
            cur = w0
    if cur:
        lines.append(cur)
    return lines

def sanitize(s):
    """keep glyphs the embedded font actually has; remap the rest."""
    rep = {"-": "\u2014", "&": "and", ";": ",", "(": "[", ")": "]",
           "/": " \u00b7 ", "+": "plus", "X": "X", "_": " "}
    out = []
    for ch in s:
        if ch == ' ' or ch in F_REG:
            out.append(ch)
        elif ch in rep:
            out.append(rep[ch])
        else:
            out.append(' ')
    return "".join(out)

# ============================ world map ============================
_GJ = json.loads(gzip.decompress(base64.b64decode(LAND_B64)))

def draw_map(x0, y0, x1, y1, sea, land, edge):
    rect(x0, y0, x1, y1, sea)
    lat_max = 84.0
    def proj(pt):
        fx = (pt[0] + 180.0) / 360.0
        fy = (lat_max - pt[1]) / (lat_max + 90.0)
        return (x0 + fx * (x1 - x0), y0 + fy * (y1 - y0))
    for feat in _GJ["features"]:
        g = feat["geometry"]
        polys = g["coordinates"]
        if g["type"] == "MultiPolygon":
            polys = [p for m in polys for p in m]
        for poly in polys:
            fill_polygon([proj(p) for p in poly], land)
    for feat in _GJ["features"]:
        g = feat["geometry"]
        polys = g["coordinates"]
        if g["type"] == "MultiPolygon":
            polys = [p for m in polys for p in m]
        for poly in polys:
            for a, b in zip(poly, poly[1:]):
                pa = proj(a); pb = proj(b)
                n = int(max(abs(pb[0] - pa[0]), abs(pb[1] - pa[1]))) + 1
                for k in range(n + 1):
                    t = k / n if n else 0
                    px(int(pa[0] + (pb[0] - pa[0]) * t),
                       int(pa[1] + (pb[1] - pa[1]) * t), edge)

# ============================ PNG writer ============================
def write_png(path, buf):
    raw = bytearray()
    for y in range(H):
        raw.append(0)
        raw += buf[y * W * 3:(y + 1) * W * 3]
    comp = zlib.compress(bytes(raw), 9)
    def chunk(tag, data):
        c = struct.pack(">I", len(data)) + tag + data
        c += struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)
        return c
    ihdr = struct.pack(">IIBBBBB", W, H, 8, 2, 0, 0, 0)
    with open(path, "wb") as f:
        f.write(b"\x89PNG\r\n\x1a\n")
        f.write(chunk(b"IHDR", ihdr))
        f.write(chunk(b"IDAT", comp))
        f.write(chunk(b"IEND", b""))


# ============================ layout ============================
def build():
    import collections
    stories = json.loads(open("/tmp/ni26-build/stories26.json").read())

    kicker = [sanitize(s) for s in stories["kicker"]]
    timeline = [(t, sanitize(s)) for t, s in stories["timeline_utc"]]
    numbers = [(sanitize(a), sanitize(b)) for a, b in stories["numbers"]]
    leads = [{"region": l["region"], "headline": sanitize(l["headline"]),
              "body": sanitize(l["body"]), "source": sanitize(l["source"])}
             for l in stories["leads"]]
    grid = [{"region": g["region"], "headline": sanitize(g["headline"]),
             "body": sanitize(g["body"]), "source": sanitize(g["source"])}
            for g in stories["grid"]]
    also = [sanitize(a) for a in stories["also"]]
    footer = sanitize(stories["footer"])
    datestr = sanitize(stories["date"])

    # ---------- masthead ----------
    rect(0, 0, W, H, PAPER)
    rect(0, 0, W, 178, INK)
    mw = text_w("THE WORLD ON ONE PAGE", 46, display=True)
    draw_text((W - mw) / 2, 58, "THE WORLD ON ONE PAGE", 46, PAPER, True, tracking=1.5)
    dw = text_w(datestr, 17)
    draw_text((W - dw) / 2, 86, datestr, 17, (200, 198, 190))
    hline(40, W - 40, 100, (90, 92, 96), 1)
    kx = 40.0
    for i, k in enumerate(kicker):
        draw_text(kx, 130, str(i + 1), 20, (230, 180, 60), display=True)
        numw = text_w(str(i + 1), 20, display=True)
        draw_text(kx + numw + 10, 130, k, 17, WHITE)
        kx += numw + 10 + text_w(k, 17) + 30
    hline(40, W - 40, 152, (90, 92, 96), 1)
    draw_text(40, 172, "EVERY STORY FIRST REPORTED OR ADVANCING TODAY \u00b7 ALL TIMES UTC",
              12, (160, 158, 150))
    hline(0, W, 178, INK, 3)

    y_top = 186
    # ---------- LEFT column: THE DAY IN UTC ----------
    LX0, LX1 = 40, 372
    draw_text(LX0, y_top + 16, "THE DAY IN UTC", 22, INK, display=True)
    hline(LX0, LX1, y_top + 26, INK, 2)
    ty = y_top + 40.0
    for t, s in timeline:
        draw_text(LX0, ty + 12, t, 13, ME, display=True)
        lines = wrap(s, 10.5, LX1 - LX0 - 52)
        yy = ty
        for ln in lines[:2]:
            draw_text(LX0 + 48, yy + 9, ln, 10.5, INK)
            yy += 11
        ty = yy + 2
    map_y0 = ty + 6
    draw_map(LX0, map_y0, LX1, map_y0 + 40, SEA, LANDC, EDGE)
    draw_text(LX0, map_y0 + 48, "THE DAY IN MAP \u00b7 NATURAL EARTH 110M COASTLINES", 10, MID)

    # ---------- RIGHT panel: IN NUMBERS ----------
    NX0, NX1 = 652, 984
    draw_text(NX0, y_top + 16, "IN NUMBERS", 22, INK, display=True)
    hline(NX0, NX1, y_top + 26, INK, 2)
    ny = y_top + 40.0
    for val, cap in numbers:
        size = 34
        while text_w(val, size) > NX1 - NX0 and size > 24:
            size -= 3
        col = MK if (val.startswith("+") or val.startswith("\u2014") or val in ("$95", "2\u00b7\u00b7")) else INK
        draw_text(NX0, ny + 30, val, size, col)
        cy = ny + 38
        for ln in wrap(cap, 10, NX1 - NX0)[:1]:
            draw_text(NX0, cy + 9, ln, 10, MID)
            cy += 11
        ny = cy + 7
        hline(NX0, NX1, ny - 6, (210, 208, 202), 1)

    # ---------- HERO BAND ----------
    hy0 = max(ny + 16, 430)
    hy1 = hy0 + 96
    rect(40, hy0, W - 40, hy1, BAND)
    frame(40, hy0, W - 40, hy1, INK, 2)
    hero = leads[0]
    rest = leads[1:]
    hx = 56.0
    hw = text_w(hero["region"], 15, display=True)
    rect(hx - 6, hy0 + 18, hx + hw + 12, hy0 + 40, ME)
    draw_text(hx, hy0 + 34, hero["region"], 15, WHITE, display=True)
    yy = hy0 + 62
    for ln in wrap(hero["headline"], 19, 310):
        draw_text(hx, yy, ln, 19, INK, display=True)
        yy += 22
    yy += 6
    for ln in wrap(hero["body"], 12.5, 310):
        draw_text(hx, yy, ln, 12.5, INK)
        yy += 15
    draw_text(hx, hy1 - 12, hero["source"], 10, MID)
    vline(hx + 330, hy0 + 12, hy1 - 12, MID, 1)
    gx = hx + 350
    colw = 200
    for ld in rest:
        c = REGION_COLOR.get(ld["region"], INK)
        tw = text_w(ld["region"], 12, display=True)
        rect(gx, hy0 + 18, gx + tw + 12, hy0 + 36, c)
        draw_text(gx + 6, hy0 + 31, ld["region"], 12, WHITE, display=True)
        yy = hy0 + 52
        for ln in wrap(ld["headline"], 14, colw - 8):
            draw_text(gx, yy, ln, 14, INK)
            yy += 16
        yy += 2
        for ln in wrap(ld["body"], 11, colw - 8)[:3]:
            draw_text(gx, yy, ln, 11, INK)
            yy += 13
        draw_text(gx, hy1 - 12, ld["source"], 9, MID)
        gx += colw + 8
        if gx < W - 56:
            vline(gx - 4, hy0 + 12, hy1 - 12, MID, 1)

    # ---------- region tally strip ----------
    ty0 = hy1 + 8
    ty1 = ty0 + 22
    frame(40, ty0, W - 40, ty1, RULE, 1)
    tx = 52.0
    tally = collections.Counter()
    for g in grid:
        tally[g["region"]] += 1
    tally[hero["region"]] += 1
    for ld in rest:
        tally[ld["region"]] += 1
    draw_text(tx, ty0 + 22, "REGION TALLY", 12, MID, display=True)
    tx += text_w("REGION TALLY", 12, True) + 24
    for reg, n in tally.most_common():
        c = REGION_COLOR.get(reg, INK)
        tw = text_w(reg, 10, True)
        rect(tx, ty0 + 4, tx + tw + 10, ty0 + 18, c)
        draw_text(tx + 5, ty0 + 14, reg, 10, WHITE, True)
        draw_text(tx + tw + 12, ty0 + 14, str(n), 11, INK, True)
        tx += tw + 26

    # ---------- 8-story grid ----------
    gy0 = ty1 + 10
    draw_text(40, gy0 + 16, "THE GRID \u00b7 EIGHT STORIES FROM THE WIRE", 20, INK, True)
    hline(40, W - 40, gy0 + 26, INK, 2)
    gy = gy0 + 34.0
    cw = (W - 80 - 24) / 2
    chh = 34
    for i, g in enumerate(grid[:6]):
        col = i % 2
        row = i // 2
        x0 = 40 + col * (cw + 24)
        y0 = gy + row * (chh + 8)
        c = REGION_COLOR.get(g["region"], INK)
        tw = text_w(g["region"], 11, True)
        rect(x0, y0, x0 + tw + 12, y0 + 16, c)
        draw_text(x0 + 6, y0 + 12, g["region"], 11, WHITE, True)
        yy = y0 + 16
        for ln in wrap(g["headline"], 12, cw)[:1]:
            draw_text(x0, yy, ln, 12, INK, True)
            yy += 13
        draw_text(x0, y0 + chh - 2, g["source"], 9, MID)

    # ---------- ALSO ON THE WIRE ----------
    ay0 = gy + 3 * (chh + 8) + 12
    draw_text(40, ay0 + 14, "ALSO ON THE WIRE", 16, INK, True)
    hline(40, W - 40, ay0 + 20, INK, 2)
    colw2 = (W - 80) / 2
    ay = ay0 + 22.0
    half = (len(also) + 1) // 2
    row_step = 9
    avail = (H - 44) - ay
    max_rows = max(2, int(avail / row_step))
    eff_half = min(half, max_rows)
    shown = eff_half * 2
    for i, a in enumerate(also[:shown]):
        col = 0 if i < eff_half else 1
        row = i % eff_half
        x0 = 40 + col * colw2
        y0 = ay + row * row_step
        draw_text(x0, y0, "\u00b7", 8, ME)
        draw_text(x0 + 7, y0, a[:70], 8.5, INK)

    # ---------- footer ----------
    fy = H - 30.0
    hline(40, W - 40, fy - 14, INK, 2)
    yy = fy
    for ln in wrap(footer, 10.5, W - 80)[:2]:
        draw_text(40, yy, ln, 10.5, MID)
        yy += 12

    write_png(os.path.join(OUT_DIR, "entry.png"), _buf)
    print("wrote", os.path.join(OUT_DIR, "entry.png"))


build()

